using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;
using System.ComponentModel;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var noteTools = host.Services.GetRequiredService<NoteTools>();

var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a research assistant. Given a topic, use the web_search tool to find "
    + "relevant information, use the add_note tool to record key findings, and then "
    + "use the get_notes tool to review all notes before providing a final summary. "
    + "Always search multiple angles of the topic and take notes on important facts.");

agent.Tools.Add(AIFunctionFactory.Create(researchTools.WebSearch));
agent.Tools.Add(AIFunctionFactory.Create(noteTools.AddNote));
agent.Tools.Add(AIFunctionFactory.Create(noteTools.GetNotes));

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

// --- Tool Definitions ---

public sealed class ResearchTools
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public string WebSearch(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing Search, Google Custom Search, etc.)
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("history") =>
                $"Search results for '{query}':\n"
                + "1. The topic has a rich history dating back centuries with key developments in multiple eras.\n"
                + "2. Major milestones include foundational discoveries and modern breakthroughs.\n"
                + "3. Historical figures played pivotal roles in shaping the field.",

            var q when q.Contains("recent") || q.Contains("2024") || q.Contains("2025") || q.Contains("2026") =>
                $"Search results for '{query}':\n"
                + "1. Recent developments show rapid advancement and increased adoption.\n"
                + "2. New research papers published in 2025-2026 highlight emerging trends.\n"
                + "3. Industry leaders are investing heavily in this area.",

            var q when q.Contains("application") || q.Contains("use") =>
                $"Search results for '{query}':\n"
                + "1. Practical applications span healthcare, finance, education, and manufacturing.\n"
                + "2. Real-world deployments have shown measurable improvements in efficiency.\n"
                + "3. Adoption continues to grow across industries.",

            _ =>
                $"Search results for '{query}':\n"
                + "1. This is an active area of research with growing interest.\n"
                + "2. Key concepts include foundational theories and practical frameworks.\n"
                + "3. Experts predict significant growth and impact in the coming years."
        };

        return results;
    }
}

public sealed class NoteTools
{
    private readonly List<string> _notes = [];

    [Description("Adds a research note to the notebook for later reference.")]
    public string AddNote(
        [Description("The note content to record")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({_notes.Count} total)");
        return $"Note recorded. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes recorded yet.";
        }

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

