using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;
using System.ComponentModel;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var noteTools = new NoteTools();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. Given a topic, use the web_search tool to find
        relevant information from multiple angles (history, recent developments, applications).
        Use the add_note tool to record key findings as you go.
        Once you have gathered enough information, use the get_notes tool to review your notes,
        then provide a comprehensive summary to the user.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools:
    [
        AIFunctionFactory.Create(WebSearchTool.Search),
        AIFunctionFactory.Create(noteTools.AddNote),
        AIFunctionFactory.Create(noteTools.GetNotes),
    ]);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

